Below is a **complete, self‑contained** example of an ASP.NET Core Minimal API that shows:

* Top‑level statements (no `Startup`/`Program` class)
* Dependency injection of a simple service
* A `WeatherForecast` model (record)  
* A few CRUD‑style endpoints (`GET`, `POST`)
* Swagger/OpenAPI integration so you can hit the API from the browser
* A tiny in‑memory repository implementation

Just copy the file into a new **.NET 8** project (or any .NET 6+ project) and run it.  
You’ll get a browser UI at `https://localhost:{port}/swagger`.

```csharp
// -----------------------------------------------------------
//  Program.cs  –  Minimal API demo
// -----------------------------------------------------------

using Microsoft.AspNetCore.Builder;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.OpenApi.Models;

// ------------------------------------------------------------------
//  1. Build the web application
// ------------------------------------------------------------------
var builder = WebApplication.CreateBuilder(args);

// Register services
builder.Services.AddSingleton<IWeatherRepository, WeatherRepository>();
builder.Services.AddEndpointsApiExplorer();   // required for Swagger
builder.Services.AddSwaggerGen(c =>
{
    c.SwaggerDoc("v1", new OpenApiInfo
    {
        Title = "Weather API (Minimal)",
        Version = "v1",
        Description = "A tiny sample of ASP.NET Core Minimal APIs."
    });
});

var app = builder.Build();

// ------------------------------------------------------------------
//  2. Middleware pipeline
// ------------------------------------------------------------------
if (app.Environment.IsDevelopment())
{
    app.UseDeveloperExceptionPage();
    app.UseSwagger();
    app.UseSwaggerUI(c =>
    {
        c.SwaggerEndpoint("/swagger/v1/swagger.json", "Weather API v1");
        c.RoutePrefix = string.Empty; // make Swagger UI available at /
    });
}

// ------------------------------------------------------------------
//  3. Endpoints
// ------------------------------------------------------------------
app.MapGet("/", () => "Hello, Minimal API!");

app.MapGet("/weatherforecast", async (IWeatherRepository repo) =>
{
    return await repo.GetAllAsync();
})
.WithName("GetAllWeather")
.Accepts<IWeatherRepository>("application/json")
.Produces<List<WeatherForecast>>(StatusCodes.Status200OK)
.Produces(StatusCodes.Status500InternalServerError);

app.MapGet("/weatherforecast/{id:int}", async (int id, IWeatherRepository repo) =>
{
    var wf = await repo.GetAsync(id);
    return wf is not null
        ? Results.Ok(wf)
        : Results.NotFound();
})
.WithName("GetWeatherById")
.Produces<WeatherForecast>(StatusCodes.Status200OK)
.Produces(StatusCodes.Status404NotFound);

app.MapPost("/weatherforecast", async (WeatherForecast newForecast, IWeatherRepository repo) =>
{
    var created = await repo.AddAsync(newForecast);
    return Results.Created($"/weatherforecast/{created.Id}", created);
})
.WithName("CreateWeather")
.Produces<WeatherForecast>(StatusCodes.Status201Created)
.Accepts<WeatherForecast>("application/json");

app.MapPut("/weatherforecast/{id:int}", async (int id, WeatherForecast update, IWeatherRepository repo) =>
{
    var existing = await repo.GetAsync(id);
    if (existing is null) return Results.NotFound();

    update.Id = id;                     // keep original ID
    await repo.UpdateAsync(update);
    return Results.NoContent();
})
.WithName("UpdateWeather")
.Produces(StatusCodes.Status204NoContent)
.Produces(StatusCodes.Status404NotFound);

app.MapDelete("/weatherforecast/{id:int}", async (int id, IWeatherRepository repo) =>
{
    var deleted = await repo.DeleteAsync(id);
    return deleted ? Results.NoContent() : Results.NotFound();
})
.WithName("DeleteWeather")
.Produces(StatusCodes.Status204NoContent)
.Produces(StatusCodes.Status404NotFound);

// ------------------------------------------------------------------
//  4. Run the application
// ------------------------------------------------------------------
app.Run();


// ------------------------------------------------------------------
//  5. Domain model & repository implementation
// ------------------------------------------------------------------

// 5.1. WeatherForecast – a simple record type
public record WeatherForecast(
    int Id,
    DateTime Date,
    int TemperatureC,
    string Summary)
{
    public double TemperatureF => 32 + TemperatureC / 0.5556;
}

// 5.2. Repository interface
public interface IWeatherRepository
{
    Task<List<WeatherForecast>> GetAllAsync();
    Task<WeatherForecast?> GetAsync(int id);
    Task<WeatherForecast> AddAsync(WeatherForecast forecast);
    Task UpdateAsync(WeatherForecast forecast);
    Task<bool> DeleteAsync(int id);
}

// 5.3. In‑memory implementation (just for demo)
public class WeatherRepository : IWeatherRepository
{
    // Simulate a database with a thread‑safe list
    private readonly List<WeatherForecast> _data = new();
    private int _nextId = 1;
    private readonly SemaphoreSlim _gate = new(1, 1);

    public WeatherRepository()
    {
        // seed with a few entries
        for (int i = 0; i < 5; i++)
            _data.Add(new WeatherForecast(
                Id: 0,
                Date: DateTime.UtcNow.AddDays(i),
                TemperatureC: Random.Shared.Next(-20, 40),
                Summary: "Sample"
            ));
        _nextId = _data.Count + 1;
    }

    public async Task<List<WeatherForecast>> GetAllAsync()
    {
        await _gate.WaitAsync();
        try
        {
            // return a copy so callers can’t mutate the backing list
            return _data.Select(x => x with { }).ToList();
        }
        finally
        {
            _gate.Release();
        }
    }

    public async Task<WeatherForecast?> GetAsync(int id)
    {
        await _gate.WaitAsync();
        try
        {
            return _data.FirstOrDefault(x => x.Id == id);
        }
        finally
        {
            _gate.Release();
        }
    }

    public async Task<WeatherForecast> AddAsync(WeatherForecast forecast)
    {
        await _gate.WaitAsync();
        try
        {
            var newItem = forecast with { Id = _nextId++ };
            _data.Add(newItem);
            return newItem;
        }
        finally
        {
            _gate.Release();
        }
    }

    public async Task UpdateAsync(WeatherForecast forecast)
    {
        await _gate.WaitAsync();
        try
        {
            var index = _data.FindIndex(x => x.Id == forecast.Id);
            if (index >= 0)
                _data[index] = forecast;
        }
        finally
        {
            _gate.Release();
        }
    }

    public async Task<bool> DeleteAsync(int id)
    {
        await _gate.WaitAsync();
        try
        {
            var item = _data.FirstOrDefault(x => x.Id == id);
            if (item is null) return false;
            _data.Remove(item);
            return true;
        }
        finally
        {
            _gate.Release();
        }
    }
}
```

### How to run

1. **Create a new project** (or add to an existing one)  
   ```bash
   dotnet new web -n MinimalWeatherApi
   cd MinimalWeatherApi
   ```
2. **Replace the generated `Program.cs`** with the code above.
3. **Add the `Microsoft.OpenApi` package** (if not already present):
   ```bash
   dotnet add package Microsoft.OpenApi
   ```
4. **Run**  
   ```bash
   dotnet run
   ```

Navigate to `https://localhost:{port}/` – you’ll see the Swagger UI with all the endpoints.  
Try the `GET /weatherforecast`, `POST /weatherforecast`, etc., to see the minimal API in action.
